#include <iostream>
#include <string>
#include <vector>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n = 10;
    vector<bool> p(n + 1, true);
    p[0] = p[1] = false;
    for (int i = 2; i * i <= n; ++i)
        if (p[i])
            for (int j = i * i; j <= n; j += i)
                p[j] = false;
    for (int i = 2; i <= n; ++i)
        if (p[i])
            cout << i << " ";
}

#include <iostream>
#include <string>
#include <vector>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    long long a = 3, b = 5, m = 100, result = 1 % m;
    a %= m;
    while (b) {
        if (b & 1)
            result = result * a % m;
        a = a * a % m;
        b /= 2;
    }
    cout << result;
}

