#include <iostream>
#include <string>
#include <vector>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    long long a, b, m;
    cin >> a >> b >> m;
    long long res = 1 % m;
    a %= m;
    while (b) {
        if (b & 1)
            res = res * a % m;
        a = a * a % m;
        b /= 2;
    }
    cout << res;
}
